export const readingExtensions: Record<string, string> = {
  "A1:introductions": "Im Kurs sitzen zehn Personen. Sie kommen aus vielen Ländern. Ich spreche zuerst mit Amir und später mit Sofia. Ich frage: „Woher kommen Sie?“ und „Wo wohnen Sie jetzt?“ Amir wohnt jetzt in Berlin. Sofia kommt aus Spanien und spricht Spanisch, Englisch und ein bisschen Deutsch. Am Ende schreiben wir unsere Namen und Sprachen auf Karten.",
  "A1:family-people": "Am Wochenende besucht Leon seine Großeltern. Seine Großmutter heißt Eva und sein Großvater heißt Paul. Sie wohnen in einem kleinen Haus. Leon hat auch einen Bruder. Er heißt Tim und arbeitet in einer Bank. Die Familie isst am Sonntag zusammen. Leon zeigt ein Foto. Auf dem Foto sind seine Mutter, sein Vater und seine Schwester.",
  "A1:time-appointments": "Mara hat diese Woche viele Termine. Am Montag arbeitet sie bis sechzehn Uhr. Am Dienstag hat sie um zehn Uhr dreißig einen Arzttermin. Am Mittwoch trifft sie eine Freundin um achtzehn Uhr. Am Freitag beginnt ihr Deutschkurs um siebzehn Uhr. Jeden Morgen schaut sie in ihren Kalender. So vergisst sie keinen Termin.",
  "A1:food-restaurants": "Auf der Karte stehen Kaffee, Tee, Wasser, Suppe, Salat und verschiedene Brötchen. Mia isst kein Fleisch und fragt nach einem vegetarischen Gericht. Der Kellner empfiehlt eine Gemüsesuppe. Mia bestellt außerdem ein Glas Wasser. Nach dem Essen bezahlt sie zwölf Euro. Sie sagt: „Danke. Die Suppe war sehr gut!“",
  "A1:daily-routine": "Unter der Woche beginnt Jonas seinen Tag früh. Nach dem Aufstehen duscht er und macht Frühstück. Um halb acht verlässt er die Wohnung. Er fährt zwanzig Minuten mit dem Bus. Nach der Arbeit kauft er manchmal Lebensmittel ein. Zu Hause kocht er und sieht kurz fern. Dann lernt er dreißig Minuten Deutsch. Danach geht er schlafen.",
  "A1:home-city": "Sofias Wohnung hat zwei Zimmer, eine Küche und ein kleines Bad. Im Wohnzimmer stehen ein Tisch und ein Sofa. Die nächste Bushaltestelle ist direkt vor dem Supermarkt. Zur Bibliothek geht Sofia zuerst geradeaus und dann an der zweiten Straße rechts. Neben der Bibliothek gibt es ein Café. Dort lernt Sofia manchmal.",
  "A1:shopping-services": "Die erste Jacke ist schwarz und günstig, aber sie ist Nora zu groß. Die zweite Jacke ist dunkelblau und passt besser. Nora fragt: „Gibt es die Jacke auch in Grün?“ Die Verkäuferin schaut im Lager nach. Am Ende nimmt Nora die blaue Jacke und bezahlt mit Karte. Den Kassenbon steckt sie in ihre Tasche.",
  "A1:travel-transport": "Am Bahnhof sieht Ben zuerst auf die große Anzeigetafel. Sein Zug nach Hamburg hat zehn Minuten Verspätung. Er kauft noch Wasser und geht dann zu Gleis sechs. In Hannover hat er zwanzig Minuten zum Umsteigen. Er fragt einen Mitarbeiter: „Von welchem Gleis fährt der nächste Zug?“ Dann findet er die Verbindung.",
  "A1:health": "Elif soll die Tabletten zweimal am Tag nehmen. Die Apothekerin fragt: „Haben Sie Fieber?“ Elif sagt: „Nein, aber ich bin ein bisschen müde.“ Zu Hause trinkt sie Tee und schläft. Morgen geht es ihr vielleicht besser. Sonst macht sie einen Termin beim Arzt. Heute bleibt sie zu Hause.",
  "A1:work-study": "Tarek arbeitet morgens von acht bis vierzehn Uhr. Danach fährt er nach Hause und macht eine kurze Pause. Zweimal pro Woche besucht er am Abend einen Deutschkurs. Er möchte mit Kunden Deutsch sprechen. Im Kurs übt er Fragen, kurze E-Mails und Gespräche. Zu Hause wiederholt er neue Wörter mit Beispielsätzen.",
  "A2:past-experiences": "Die Wanderung dauerte fast vier Stunden. Unterwegs hat die Gruppe eine Pause an einem kleinen Aussichtspunkt gemacht. Hanna hatte ihre Kamera dabei und hat viele Fotos gemacht. Später begann es kurz zu regnen, aber niemand wollte umkehren. Nach der Wanderung waren alle müde. Beim gemeinsamen Abendessen erzählten sie, welcher Teil des Tages ihnen am besten gefallen hatte. Hanna merkte, dass sie längere Wege inzwischen besser schafft als früher.",
  "A2:housing-moving": "Bei der Besichtigung sieht Mina ein helles Wohnzimmer, ein kleines Schlafzimmer und eine moderne Küche. Der Vermieter erklärt, welche Möbel in der Wohnung bleiben. Mina fragt, ob Haustiere erlaubt sind und wo sie ihr Fahrrad abstellen kann. Die Lage gefällt ihr sehr, weil die Straßenbahn direkt vor dem Haus hält. Bevor sie sich entscheidet, möchte sie aber noch wissen, wie hoch die gesamten monatlichen Kosten sind und ab wann die Wohnung verfügbar wäre.",
  "A2:health-appointments": "In der Praxis muss David zuerst ein Formular ausfüllen. Danach wartet er ungefähr zwanzig Minuten. Der Arzt untersucht seinen Hals und hört seine Lunge ab. Er empfiehlt David, viel zu trinken und sich einige Tage zu schonen. Weil David bei der Arbeit viel sprechen muss, fragt er, ob er zu Hause bleiben sollte. Der Arzt schreibt ihn für zwei Tage krank und sagt, dass er wiederkommen soll, falls das Fieber steigt.",
  "A2:travel-problems": "Die Mitarbeiterin erklärt Karim, dass er mit seinem bisherigen Ticket die alternative Verbindung benutzen darf. Der neue Zug fährt zwar später ab, kommt aber nur fünfundzwanzig Minuten nach der ursprünglichen Ankunftszeit in München an. Karim fragt zusätzlich, ob er einen Sitzplatz reservieren kann. Da der Zug ziemlich voll ist, empfiehlt die Mitarbeiterin eine Reservierung. Karim informiert anschließend die Person, die ihn in München abholen wollte, über die neue Ankunftszeit.",
  "A2:work-routines": "An normalen Tagen plant Lena ihre Aufgaben am Morgen und markiert dringende Termine. Wenn viele Anfragen gleichzeitig kommen, spricht sie kurz mit ihrer Teamleitung über die Prioritäten. Heute muss sie außerdem eine Präsentation vorbereiten. Deshalb bittet sie einen Kollegen, einige Telefonate zu übernehmen. Am Nachmittag überprüft sie, welche Aufgaben erledigt sind, und verschiebt zwei weniger wichtige Punkte auf den nächsten Tag.",
  "A2:learning-education": "Nico hat früher versucht, jeden Tag sehr lange Wortlisten zu lernen. Nach einigen Wochen stellte er fest, dass er viele Wörter schnell wieder vergaß. Jetzt sammelt er kurze Beispielsätze und wiederholt ältere Wörter mehrmals pro Woche. Außerdem hört er einfache Podcasts und notiert Ausdrücke, die häufig vorkommen. Wenn er einen Fehler macht, schreibt er den richtigen Satz in ein kleines Fehlerheft. Dadurch kann er seine typischen Probleme besser erkennen.",
  "A2:media-technology": "Der Support antwortet Sara am nächsten Morgen. Zuerst soll sie prüfen, ob sie die aktuelle Version der App installiert hat. Danach soll sie das Passwort zurücksetzen und die App neu starten. Sara probiert die Schritte aus, aber das Problem bleibt bestehen. Sie macht deshalb einen Screenshot der Fehlermeldung und schickt ihn an den Support. Einige Stunden später bekommt sie eine neue Nachricht mit einer vorläufigen Lösung.",
  "A2:social-life": "Das Restaurant liegt in der Nähe einer U-Bahn-Station, deshalb können alle leicht dorthin kommen. Lea reserviert einen Tisch für vier Personen. Samir kommt etwas später, weil er bis achtzehn Uhr arbeiten muss. Nach dem Essen möchten sie noch spazieren gehen, wenn das Wetter gut bleibt. Eine Freundin kann kurzfristig nicht kommen und schreibt eine Nachricht. Die Gruppe verschiebt das nächste gemeinsame Treffen deshalb auf das folgende Wochenende.",
  "A2:consumer-life": "Der Kundenservice bietet Omar zunächst einen Austausch an. Omar möchte jedoch lieber sein Geld zurück, weil er inzwischen ein anderes Modell gefunden hat. Er erklärt, wann er die Kopfhörer bestellt hat und welches Problem aufgetreten ist. Die Mitarbeiterin schickt ihm ein Rücksendeetikett. Omar verpackt das Produkt wieder und gibt das Paket am nächsten Tag ab. Eine Woche später sieht er die Rückzahlung auf seinem Konto.",
  "A2:plans-future": "Aylin erstellt für die nächsten Monate einen einfachen Plan. Zuerst möchte sie jeden Tag dreißig Minuten Deutsch lernen. Im Herbst wird sie einen beruflichen Kurs besuchen und parallel nach einem Praktikumsplatz suchen. Bevor sie Bewerbungen verschickt, will sie ihren Lebenslauf aktualisieren. Sie weiß, dass nicht jeder Schritt sofort funktionieren wird, aber sie möchte regelmäßig prüfen, was sie bereits erreicht hat und was sie noch ändern muss.",
  "B1:narrating": "Am nächsten Morgen entschied Felix, die Stadt ohne festen Plan zu erkunden. Er lief zunächst durch ein Wohnviertel, in dem kaum Touristen unterwegs waren, und setzte sich später in ein kleines Café. Dort erklärte ihm die Besitzerin, welche Orte sie selbst gern besucht. Felix folgte einigen ihrer Empfehlungen und entdeckte dadurch Seiten der Stadt, die in seinem Reiseführer kaum erwähnt wurden. Rückblickend fand er gerade die unerwarteten Situationen besonders wertvoll. Die Probleme bei der Ankunft hatten ihn zuerst gestresst, aber sie zwangen ihn auch dazu, mit anderen Menschen zu sprechen und spontaner zu handeln. Seit dieser Reise plant er weniger genau und lässt bewusst Zeit für ungeplante Erfahrungen.",
  "B1:career": "Maja vergleicht die Anforderungen der neuen Stelle mit ihren bisherigen Aufgaben. Einige Punkte kennt sie bereits gut, andere wären neu für sie. Besonders interessiert sie, dass das Unternehmen Mitarbeitende an internen Projekten beteiligt und Weiterbildung unterstützt. Für das Anschreiben wählt sie zwei konkrete Beispiele aus ihrer aktuellen Arbeit: eine Auswertung, durch die ein wiederkehrendes Problem sichtbar wurde, und ein Projekt, bei dem sie Informationen aus mehreren Abteilungen koordinieren musste. Im Vorstellungsgespräch möchte sie nicht nur ihre Stärken nennen, sondern auch erklären, warum sie sich fachlich weiterentwickeln will. Gleichzeitig bereitet sie Fragen zur Einarbeitung, zu den Erwartungen in den ersten Monaten und zur Zusammenarbeit im Team vor.",
  "B1:education": "Die Lerngruppe trifft sich jeden Mittwoch für neunzig Minuten. Zu Beginn nennt jede Person ein Thema, das noch unsicher ist. Danach erklären die Teilnehmenden sich gegenseitig Aufgaben, statt einfach nur Lösungen vorzulesen. Wenn niemand eine Frage beantworten kann, markieren sie sie für den nächsten Kurstermin. Kurz vor der Prüfung verkürzen sie die Treffen und konzentrieren sich stärker auf typische Aufgabenformate. Ein Student merkt, dass er beim gemeinsamen Lernen manchmal zu viel Zeit mit Diskussionen verliert. Deshalb bearbeitet er schwierige Übungen zuerst allein und nutzt die Gruppe anschließend, um seine Lösung zu überprüfen. Für ihn funktioniert die Kombination aus selbstständigem Arbeiten und gezieltem Austausch am besten.",
  "B1:wellbeing": "Eine feste Routine hilft vielen Menschen mehr als ein sehr ambitionierter Plan, der nur wenige Tage durchgehalten wird. Wer beispielsweise jeden Abend eine halbe Stunde früher mit der Arbeit aufhört, kann diese Zeit für Bewegung, Kochen oder Entspannung nutzen. Gleichzeitig unterscheiden sich die Ursachen von Stress. Manche Menschen haben zu viele Aufgaben, andere können nach Feierabend gedanklich nicht abschalten. Deshalb ist es sinnvoll, zunächst zu beobachten, in welchen Situationen die Belastung besonders stark wird. Kleine Veränderungen lösen nicht jedes Problem, können aber zeigen, welche Gewohnheiten wirklich helfen. Wenn Beschwerden lange anhalten oder den Alltag stark einschränken, sollte professionelle Unterstützung gesucht werden.",
  "B1:environment": "Die neuen Fahrradwege sind Teil eines größeren Verkehrskonzepts. Neben sicheren Radverbindungen sollen Bushaltestellen verbessert und einige Straßen stärker begrünt werden. Geschäftsleute befürchten, dass weniger Parkplätze Kundschaft kosten könnten. Andere erwarten dagegen, dass ruhigere Straßen mehr Menschen zu Fuß in das Viertel bringen. Die Stadt will die Veränderungen zunächst ein Jahr lang beobachten. Dabei werden Verkehrszahlen, Beschwerden und die Nutzung der neuen Wege erfasst. Erst danach soll entschieden werden, welche Maßnahmen dauerhaft bleiben. In der öffentlichen Diskussion wird deutlich, dass Umweltschutz, Erreichbarkeit und wirtschaftliche Interessen nicht immer leicht miteinander zu verbinden sind.",
  "B1:media-opinion": "Besonders problematisch sind Meldungen, die starke Gefühle auslösen und deshalb sehr schnell weitergeleitet werden. Ein kurzer Beitrag kann korrekt beginnen, aber wichtige Hintergründe weglassen. Um eine Information einzuschätzen, lohnt es sich deshalb, die ursprüngliche Quelle zu suchen und zu prüfen, ob andere seriöse Medien denselben Sachverhalt ähnlich beschreiben. Auch Bilder sollten nicht automatisch als Beweis verstanden werden, weil sie aus einem anderen Zusammenhang stammen können. In einer Schulung lernen die Teilnehmenden, zwischen Nachricht, Kommentar und Werbung zu unterscheiden. Am Ende vergleichen sie zwei Beiträge zum gleichen Thema und diskutieren, welche Informationen fehlen und welche Formulierungen besonders wertend wirken.",
  "B1:travel-culture": "Einige Unterschiede betreffen einfache Alltagsroutinen, etwa Essenszeiten, Pünktlichkeit oder die Art, wie Menschen Kritik äußern. Wer neu in einem Land ist, interpretiert ungewohnte Reaktionen leicht nach den Regeln der eigenen Kultur. Dadurch können Missverständnisse entstehen, obwohl niemand unhöflich sein wollte. Hilfreich ist es, nachzufragen, statt sofort eine Absicht zu vermuten. Reisende, die länger bleiben, entwickeln oft eigene Strategien: Sie beobachten zunächst, sprechen mit Menschen vor Ort und vergleichen verschiedene Situationen. Mit der Zeit verstehen sie besser, welche Regeln tatsächlich allgemein gelten und welche nur persönliche Gewohnheiten einzelner Personen sind.",
  "B1:housing-admin": "Nadia liest den Brief mehrmals, weil einige Formulierungen ungewohnt sind. Sie markiert die Frist und erstellt eine Liste der verlangten Dokumente. Zwei Unterlagen kann sie sofort hochladen, die dritte erhält sie erst nach einem Termin bei einer anderen Stelle. In ihrer E-Mail nennt sie deshalb das Aktenzeichen, erklärt kurz die Situation und bittet um Bestätigung, dass eine spätere Einreichung möglich ist. Am nächsten Tag erhält sie eine Antwort. Die Behörde verlängert die Frist um eine Woche. Nadia speichert die Nachricht zusammen mit den übrigen Unterlagen, damit sie später nachvollziehen kann, was vereinbart wurde.",
  "B1:community": "Nach den ersten Monaten stellt das Projektteam fest, dass vor allem Menschen teilnehmen, die bereits andere Personen im Viertel kennen. Neu zugezogene Bewohner erfahren dagegen selten von den Angeboten. Die Freiwilligen verteilen deshalb Informationen in mehreren Sprachen und arbeiten mit Schulen, Sportvereinen und Beratungsstellen zusammen. Außerdem führen sie einmal im Monat ein offenes Treffen ohne festes Programm ein. Dort können Bewohner eigene Ideen vorschlagen. Einige wünschen sich einen Reparaturabend, andere einen gemeinsamen Garten. Das Team kann nicht alles gleichzeitig umsetzen und entwickelt deshalb einfache Kriterien: Wie viele Menschen profitieren, welche Kosten entstehen und wer übernimmt die Verantwortung?",
  "B1:problems-solutions": "Im ersten Schritt sammelt das Team alle laufenden Aufgaben und ordnet sie nach Dringlichkeit und Wirkung. Dabei wird sichtbar, dass mehrere Projekte ähnliche Informationen benötigen, aber unabhängig voneinander bearbeitet werden. Die Teamleitung schlägt vor, diese Arbeiten zusammenzuführen. Außerdem soll jede Woche eine kurze Besprechung stattfinden, in der nur Blockaden und Prioritäten geklärt werden. Nach vier Wochen überprüft das Team, ob weniger Termine verschoben wurden. Nicht jede Schwierigkeit ist verschwunden, doch die Mitarbeitenden wissen besser, worauf sie sich konzentrieren sollen. Entscheidend war, nicht sofort eine komplizierte neue Software einzuführen, sondern zunächst den Arbeitsprozess selbst verständlicher zu machen.",
  "B2:argumentation": "Ein überzeugender Beitrag beginnt deshalb mit einer klaren Fragestellung und unterscheidet zwischen Behauptungen, Beispielen und Belegen. Wer eine Gegenposition nur in ihrer schwächsten Form darstellt, macht es sich zu leicht und überzeugt kritische Leser selten. Sinnvoller ist es, das stärkste relevante Gegenargument fair zusammenzufassen und anschließend zu zeigen, warum die eigene Schlussfolgerung trotzdem trägt oder unter welchen Bedingungen sie eingeschränkt werden muss. Auch die Reihenfolge spielt eine Rolle: Manche Texte nennen zuerst gemeinsame Ausgangspunkte, bevor sie den eigentlichen Konflikt erklären. Andere beginnen mit einer überraschenden Beobachtung und entwickeln daraus ihre These. In beiden Fällen sollte am Ende deutlich werden, welche Aussage tatsächlich begründet wurde und welche Fragen offenbleiben.",
  "B2:professional-work": "Im nächsten Statusgespräch werden die offenen Punkte nicht nur aufgezählt, sondern nach Auswirkung und Verantwortlichkeit geordnet. Ein technisches Problem kann intern gelöst werden, während die fehlende Freigabe von einer externen Entscheidung abhängt. Die Projektleitung trennt deshalb Risiken, die das Team selbst beeinflussen kann, von Abhängigkeiten, die nur beobachtet oder eskaliert werden können. Für jede kritische Aufgabe werden ein nächster Schritt, eine verantwortliche Person und ein realistischer Termin festgelegt. Dadurch wird vermieden, dass allgemeine Formulierungen wie „muss dringend geklärt werden“ ohne konkrete Konsequenz im Protokoll stehen bleiben. Gleichzeitig achtet die Leitung darauf, Unsicherheit offen zu benennen, statt einen scheinbar sicheren Termin zu versprechen.",
  "B2:technology": "Bei der Einführung eines solchen Systems müssen außerdem organisatorische Fragen geklärt werden. Wer darf Ergebnisse sehen, wer prüft auffällige Fälle und wie werden Fehler dokumentiert? Wenn Mitarbeitende die Funktionsweise überhaupt nicht verstehen, besteht die Gefahr, dass sie Ergebnisse entweder blind akzeptieren oder grundsätzlich ablehnen. Deshalb kombinieren einige Organisationen technische Tests mit klaren Arbeitsregeln und Schulungen. Ein weiterer Punkt ist die Qualität der Ausgangsdaten. Historische Datensätze können Lücken, Verzerrungen oder veraltete Kategorien enthalten. Selbst ein leistungsfähiges Modell kann daraus problematische Schlussfolgerungen erzeugen. Eine verantwortungsvolle Einführung betrachtet daher nicht nur Genauigkeit, sondern auch Nachvollziehbarkeit, Zuständigkeiten und die Möglichkeit, Entscheidungen zu korrigieren.",
  "B2:society": "Ein Beispiel dafür ist die Ausbreitung flexibler Arbeitsformen. Für manche Beschäftigte erleichtert sie die Vereinbarkeit von Beruf und Familie, andere verfügen zu Hause weder über geeigneten Platz noch über ausreichende technische Ausstattung. Auch Unternehmen unterscheiden sich darin, wie stark Aufgaben auf informellen Austausch angewiesen sind. Wer nur Durchschnittswerte betrachtet, übersieht solche Unterschiede leicht. In einer differenzierten Analyse werden deshalb verschiedene Gruppen, Tätigkeiten und Zeiträume getrennt untersucht. Zudem sollte zwischen dem Wunsch nach Flexibilität und den tatsächlichen Folgen unterschieden werden. Eine Maßnahme kann von vielen Menschen positiv bewertet werden und dennoch unbeabsichtigte Nachteile für bestimmte Gruppen erzeugen. Politische und betriebliche Entscheidungen müssen diese Spannungen sichtbar machen.",
  "B2:climate-environment": "Nehmen wir die energetische Sanierung von Gebäuden. Eine gute Dämmung kann den Heizbedarf deutlich reduzieren, verursacht aber zunächst Kosten und erfordert Fachkräfte. In einem alten Mehrfamilienhaus stellen sich außerdem andere technische Fragen als in einem neuen Bürogebäude. Förderprogramme können Investitionen erleichtern, doch ihre Wirkung hängt davon ab, ob Eigentümer die Regeln verstehen und ob genügend Kapazitäten für die Umsetzung vorhanden sind. Bei der Bewertung sollte deshalb nicht nur der theoretisch mögliche Energiegewinn betrachtet werden. Relevant sind auch tatsächliche Nutzung, Lebensdauer der Maßnahmen, soziale Folgen und die Frage, wer die Kosten trägt. Erst aus diesem Gesamtbild lässt sich ableiten, welche Kombination von Maßnahmen in einer konkreten Situation sinnvoll ist.",
  "B2:media-communication": "Ein besonders wirkungsvolles Mittel ist die Auswahl des Vergleichsrahmens. Eine Zahl kann im Vergleich zum Vormonat stark steigen und im Vergleich zum langfristigen Durchschnitt trotzdem unauffällig sein. Überschriften nutzen solche Kontraste häufig, weil sie Aufmerksamkeit erzeugen. Seriöse Analyse fragt deshalb: Welche Zeiträume werden verglichen, welche Quelle liefert die Daten und welche Informationen fehlen? Auch Zitate können unterschiedlich wirken, je nachdem, welcher Satz ausgewählt und welcher Kontext weggelassen wird. Das bedeutet nicht, dass jede redaktionelle Entscheidung manipulativ ist; Medien müssen zwangsläufig auswählen und verdichten. Entscheidend ist vielmehr, ob die Darstellung zentrale Einschränkungen fair vermittelt und ob Leser erkennen können, welche Aussage auf Daten, welche auf Interpretation und welche auf Meinung beruht.",
  "B2:education-policy": "Das zeigt sich etwa bei der Diskussion über Präsenz- und Online-Unterricht. Ein Kurs kann digital hervorragend funktionieren, wenn Aufgaben klar strukturiert sind, Lernende regelmäßig Rückmeldung erhalten und technische Hürden gering bleiben. Derselbe Kurs kann für Personen mit wenig Lernerfahrung oder instabiler Internetverbindung deutlich schwieriger sein. Umgekehrt garantiert ein Präsenzformat noch keine aktive Beteiligung. Bei Vergleichen sollte deshalb genauer beschrieben werden, welche Zielgruppe, welches Fach und welche Art von Lernaktivität untersucht wurde. Aussagen wie „Online-Lernen ist effektiver“ oder „Präsenz ist immer besser“ sind meist zu allgemein. Sinnvoller ist die Frage, unter welchen Bedingungen ein bestimmtes Format welche Lernziele besonders gut unterstützt.",
  "B2:economy-consumer": "Bei Investitionsentscheidungen wird häufig zwischen Anschaffungskosten und Gesamtkosten über die Nutzungsdauer unterschieden. Ein günstiges Gerät kann teuer werden, wenn es häufig ausfällt, viel Energie verbraucht oder nur schwer repariert werden kann. Gleichzeitig ist eine teurere Lösung nicht automatisch wirtschaftlicher. Die erwartete Nutzungsdauer, Finanzierung, technologische Entwicklung und das tatsächliche Einsatzprofil verändern die Rechnung. Verbraucher treffen ähnliche Entscheidungen, auch wenn sie nicht jede Größe formal berechnen. Sie gewichten Preis, Qualität, Vertrauen, Bequemlichkeit und Risiko unterschiedlich. Unternehmen versuchen dieses Verhalten mit Angeboten und Preismodellen zu beeinflussen. Eine gute Analyse trennt daher den unmittelbaren Preisreiz von den längerfristigen Konsequenzen.",
  "B2:culture-identity": "Mehrsprachigkeit zeigt besonders deutlich, dass Identität nicht wie ein fester Gegenstand funktioniert. Eine Person kann sich gleichzeitig mit mehreren Orten, Gruppen oder Sprachen verbunden fühlen, ohne diese Zugehörigkeiten als Widerspruch zu erleben. Welche Sprache in einer Situation gewählt wird, hängt unter anderem von Gesprächspartnern, Thema, Erinnerung und sozialem Umfeld ab. Manche Menschen empfinden eine Sprache als emotional näher, obwohl sie eine andere beruflich sicherer beherrschen. Solche Erfahrungen dürfen jedoch nicht verallgemeinert werden. Auch innerhalb derselben Familie können Geschwister ihre sprachliche Identität unterschiedlich beschreiben. Eine differenzierte Diskussion lässt deshalb Raum für individuelle Biografien und vermeidet die Vorstellung, eine bestimmte Sprache müsse automatisch eine bestimmte kulturelle Haltung erzeugen.",
  "B2:presentations": "Vor einer Präsentation lohnt es sich deshalb, für jede wichtige Zahl eine kurze Erklärung vorzubereiten: Was genau wird gemessen, im Vergleich wozu und mit welcher Einschränkung? Ein Diagramm sollte die Argumentation unterstützen, nicht ersetzen. Wenn mehrere Entwicklungen gleichzeitig sichtbar sind, hilft es, zunächst den wichtigsten Trend zu benennen und erst danach Ausnahmen zu erklären. In der Fragerunde verändert sich die Aufgabe. Vortragende müssen spontan erkennen, ob jemand nach einer Definition, einem Beleg oder einer Bewertung fragt. Eine gute Antwort kann eine Grenze der eigenen Analyse offen nennen, ohne dadurch unsicher zu wirken. Formulierungen wie „Aus diesen Daten lässt sich das nicht direkt ableiten“ erhöhen oft die Glaubwürdigkeit, weil sie Beobachtung und Interpretation sauber trennen.",
  "C1:academic-discourse": "Beim wissenschaftsnahen Lesen ist darüber hinaus entscheidend, den Status einzelner Aussagen zu bestimmen. Ein Autor kann einen Befund referieren, eine methodische Einschränkung nennen und anschließend eine eigene Interpretation entwickeln. Werden diese Ebenen nicht auseinandergehalten, entsteht schnell der Eindruck, jede Formulierung besitze denselben Grad an Gewissheit. Fortgeschrittene Leser achten daher auf Verben der Zuschreibung, Einschränkungen, Konnektoren und die Position einer Aussage im Argumentationsgang. Ebenso wichtig ist die Frage, welche Alternativerklärungen ausgeschlossen wurden und welche nicht. Eine überzeugende Synthese fasst deshalb nicht bloß Absätze nacheinander zusammen. Sie ordnet Befunde nach ihrer Funktion, verbindet übereinstimmende Punkte verschiedener Quellen und markiert Widersprüche oder offene Fragen. Dabei muss die eigene Darstellung sprachlich kompakt bleiben, ohne Unsicherheit künstlich zu beseitigen. Gerade bei komplexen Themen ist Präzision häufig wichtiger als eine spektakulär eindeutige Schlussfolgerung.",
  "C1:formal-writing": "Ein präzises Memo beginnt beispielsweise nicht mit einer langen Vorgeschichte, sondern mit dem Anlass und der Frage, die entschieden werden muss. Danach folgen nur die Informationen, die für diese Entscheidung relevant sind. Beobachtungen, Annahmen und Empfehlungen sollten sprachlich klar voneinander getrennt werden. Formulierungen wie „nach aktuellem Stand“ oder „unter der Voraussetzung, dass“ können Unsicherheit transparent machen, während unpersönliche Wendungen Verantwortlichkeit nicht verschleiern dürfen. Auch Höflichkeit bedeutet in professionellen Texten nicht, jede Aussage abzuschwächen. Eine Frist, ein Risiko oder eine erforderliche Handlung muss eindeutig erkennbar bleiben. Gute formelle Kommunikation schafft damit zwei Dinge gleichzeitig: Sie reduziert Interpretationsspielraum und respektiert die Beziehung zwischen den Beteiligten. Vor dem Versenden lohnt sich eine letzte Prüfung: Ist klar, wer was bis wann tun soll, welche Information belegt ist und an welcher Stelle noch eine Entscheidung aussteht?",
  "C1:nuanced-argument": "Qualifizierte Argumentation arbeitet deshalb mit Abstufungen statt mit pauschalen Urteilen. Ein Befund kann robust, plausibel, vorläufig oder lediglich mit einer Hypothese vereinbar sein. Diese Unterschiede sollten sich in der Sprache widerspiegeln. Wer jede Unsicherheit als Schwäche behandelt, riskiert Übertreibungen; wer dagegen jede Aussage so stark relativiert, dass keine Position mehr erkennbar ist, verliert argumentative Klarheit. Besonders anspruchsvoll ist der Umgang mit Gegenbeispielen. Ein einzelner Ausnahmefall widerlegt nicht automatisch eine allgemeine Tendenz, kann aber zeigen, dass deren Geltungsbereich enger ist als zunächst angenommen. Fortgeschrittene Sprecher und Schreiber formulieren daher nicht nur, *was* sie denken, sondern auch, *unter welchen Bedingungen* ihre Aussage gelten soll. Auf diese Weise werden Einschränkungen Teil des Arguments statt nachträgliche Entschuldigungen.",
  "C1:data-reports": "Bei der Interpretation von Kennzahlen treten häufig drei Ebenen durcheinander: Messung, Vergleich und Erklärung. Zunächst muss geklärt werden, was der Indikator tatsächlich erfasst und ob sich Definition oder Datengrundlage im Zeitverlauf verändert haben. Erst dann ist ein Vergleich sinnvoll. Selbst ein deutlicher Unterschied beantwortet jedoch noch nicht die Frage nach seiner Ursache. Dafür müssen alternative Einflussfaktoren geprüft werden. In einem professionellen Bericht sollte deshalb zwischen Sätzen wie „der Anteil stieg um fünf Prozentpunkte“ und „die Maßnahme führte zu diesem Anstieg“ klar unterschieden werden. Die zweite Aussage enthält eine kausale Interpretation und benötigt zusätzliche Evidenz. Ebenso relevant ist die Auswahl der Bezugsgröße: Absolute Werte, Prozentwerte und Raten können unterschiedliche Eindrücke erzeugen. Ein belastbarer Datenkommentar nennt deshalb Zeitraum, Population und Unsicherheit, bevor operative Konsequenzen vorgeschlagen werden.",
  "C1:negotiation": "In anspruchsvollen Verhandlungen liegen die Interessen häufig nicht exakt dort, wo die zunächst formulierten Positionen vermuten lassen. Eine Abteilung fordert vielleicht einen bestimmten Termin, weil eine externe Zusage daran hängt; die andere lehnt ihn ab, weil Qualitätsrisiken entstehen würden. Wenn beide Seiten nur über das Datum streiten, bleibt der eigentliche Konflikt verborgen. Produktiver ist es, die zugrunde liegenden Interessen explizit zu machen und mehrere Kombinationen von Umfang, Zeit und Ressourcen zu prüfen. Sprachlich erfordert das eine Balance aus Klarheit und Offenheit. Ein Satz wie „Unter diesen Voraussetzungen können wir Freitag nicht verantworten“ markiert eine Grenze, lässt aber Raum dafür, die Voraussetzungen zu verändern. Gleichzeitig sollten Zugeständnisse konkret formuliert werden, damit später keine unterschiedlichen Erwartungen entstehen. Eine tragfähige Vereinbarung benennt daher nicht nur das Ergebnis, sondern auch Bedingungen, Zuständigkeiten und den Umgang mit neuen Informationen.",
  "C1:media-analysis": "Quellenintegration ist dabei ein zentraler Prüfstein. Ein Beitrag kann sich auf eine Studie berufen, ohne deren Design, Zeitraum oder Einschränkungen angemessen wiederzugeben. Ein anderer kann dieselbe Studie kritisieren, dabei jedoch nur einen besonders schwachen Teil der Argumentation auswählen. Fortgeschrittene Analyse rekonstruiert deshalb zunächst, was eine Quelle tatsächlich behauptet, bevor die journalistische oder argumentative Verwendung bewertet wird. Auch sprachliche Zuschreibung spielt eine Rolle: „Die Daten zeigen“ klingt stärker als „die Autoren interpretieren die Daten als Hinweis“. Solche Unterschiede verändern, wie sicher eine Aussage wahrgenommen wird. Darüber hinaus sollte untersucht werden, welche Stimmen fehlen. Nicht jede fehlende Perspektive ist automatisch ein Fehler, doch die Auswahl beeinflusst den Rahmen des Beitrags. Ziel ist keine zynische Haltung, nach der jede Darstellung bloße Manipulation wäre, sondern eine methodische Trennung von Information, Auswahl, Interpretation und rhetorischer Wirkung.",
  "C1:science-ethics": "Ein typischer Konflikt entsteht, wenn eine technische Anwendung einen messbaren Nutzen verspricht, dafür aber neue Formen der Datenerhebung oder Kontrolle benötigt. Eine rein technische Bewertung könnte fragen, wie genau das System arbeitet; eine ethische Analyse fragt zusätzlich, wer Risiken trägt, wer zustimmt und wer Entscheidungen anfechten kann. Dabei gibt es selten nur zwei Positionen. Zwischen vollständigem Verzicht und uneingeschränktem Einsatz liegen Möglichkeiten wie begrenzte Anwendungsbereiche, unabhängige Prüfungen, transparente Dokumentation oder zeitlich befristete Pilotprojekte. Auch Werte können miteinander konkurrieren: Sicherheit, Autonomie, Gleichbehandlung und Effizienz lassen sich nicht in jeder Situation gleichzeitig maximieren. Eine verantwortliche Entscheidung macht diese Zielkonflikte sichtbar und begründet, warum bestimmte Prioritäten gesetzt werden. Entscheidend ist, technische Möglichkeiten nicht mit normativen Schlussfolgerungen zu verwechseln.",
  "C1:institutions-society": "Institutionelle Regeln verändern Verhalten, weil Menschen und Organisationen auf Anreize reagieren. Wird beispielsweise nur eine einzelne Kennzahl zum Erfolgsmaß erklärt, können Beteiligte beginnen, ihre Arbeit stark auf diese Kennzahl auszurichten, selbst wenn andere wichtige Ziele darunter leiden. Das bedeutet nicht, dass Messung grundsätzlich schädlich wäre. Vielmehr muss untersucht werden, welche Reaktionen eine Regel wahrscheinlich auslöst und welche Informationen sie nicht erfasst. Hinzu kommt, dass dieselbe Regel in unterschiedlichen institutionellen Umgebungen anders wirken kann. Ressourcen, Kontrollmöglichkeiten und bestehende Normen beeinflussen ihre praktische Umsetzung. Eine sorgfältige Analyse trennt daher Ziel, Mechanismus und beobachtetes Ergebnis. Wenn unerwartete Folgen auftreten, sollte nicht vorschnell geschlossen werden, die ursprüngliche Absicht sei falsch gewesen; möglicherweise war der angenommene Wirkungsmechanismus unvollständig oder wurde durch andere Anreize überlagert.",
  "C1:presentations-debate": "Eine belastbare Präsentation ist deshalb modular aufgebaut: Das Publikum sollte jederzeit erkennen können, welche Frage gerade beantwortet wird und wie dieser Abschnitt zur Gesamtaussage beiträgt. Bei komplexen Themen hilft es, zwischen Befund, Interpretation und Empfehlung explizit zu unterscheiden. In der Diskussion danach verschiebt sich der Schwerpunkt von vorbereiteter Darstellung zu spontaner Interaktion. Kritische Fragen testen häufig nicht nur Fachwissen, sondern auch die Fähigkeit, Grenzen einzuräumen und dennoch eine klare Position zu behalten. Wer eine Frage missverstanden hat, sollte sie reformulieren oder um Präzisierung bitten, statt sofort eine vorbereitete Antwort zu geben. Ebenso legitim ist es, einen Punkt offen zu lassen, wenn die vorhandenen Informationen keine belastbare Aussage erlauben. Fortgeschrittene kommunikative Kompetenz zeigt sich gerade darin, Unsicherheit präzise auszudrücken und anschließend wieder zur zentralen Argumentationslinie zurückzuführen.",
  "C1:synthesis-mastery": "Bei einer Syntheseaufgabe müssen Informationen verschiedener Quellen nach Themen oder Argumenten geordnet werden, nicht nach der Reihenfolge, in der sie gelesen wurden. Zwei Quellen können dieselbe Entwicklung beschreiben, aber unterschiedliche Ursachen betonen oder verschiedene Bewertungsmaßstäbe verwenden. Eine gute Zusammenführung nennt zunächst den gemeinsamen Kern und arbeitet anschließend Unterschiede heraus. Eigene Bewertung sollte klar von der Wiedergabe der Quellen getrennt bleiben. Unter Zeitdruck hilft eine kurze Planung: zentrale Frage, zwei bis drei Vergleichsdimensionen, wichtigste Belege, Einschränkungen und Schlussfolgerung. In der mündlichen Phase kommt hinzu, dass Rückfragen neue Aspekte eröffnen können. Statt eine vorbereitete Formulierung zu verteidigen, sollte die Position bei überzeugenden Einwänden präzisiert werden. C1 bedeutet nicht Fehlerfreiheit, sondern die Fähigkeit, komplexe Bedeutung flexibel, kohärent und mit hoher sprachlicher Kontrolle auszudrücken."
};

export const advancedReadingExtensions: Record<string, string> = {
  "B2:argumentation": "Zusätzlich muss die Qualität der verwendeten Belege bewertet werden. Ein anschauliches Einzelbeispiel kann ein Problem verständlich machen, sagt aber wenig darüber aus, wie häufig es insgesamt auftritt. Umgekehrt kann eine große Zahl beeindruckend wirken, ohne für die konkrete Fragestellung relevant zu sein. Gute Argumentation erklärt deshalb, warum ein bestimmter Beleg zur These passt und welche Grenzen er besitzt. Auch die Auswahl von Begriffen verdient Aufmerksamkeit. Wer von „Kosten“, „Investitionen“ oder „Belastungen“ spricht, rahmt denselben Vorgang unterschiedlich. Die sprachliche Analyse ersetzt dabei nicht die sachliche Prüfung, sondern ergänzt sie. Ziel ist eine Schlussfolgerung, die stark genug formuliert ist, um eine Position erkennbar zu machen, und zugleich offenlegt, an welchen Punkten vernünftiger Widerspruch möglich bleibt.",
  "B2:professional-work": "In einem späteren Gespräch zeigt sich, dass zwei Teams dieselbe Aufgabe unterschiedlich verstanden haben. Statt die Diskussion auf die Frage zu reduzieren, wer den Fehler verursacht hat, rekonstruiert die Projektleitung die Entscheidungswege. Eine Anforderung war in einer frühen Version des Dokuments anders formuliert und wurde nach einer Änderung nicht überall aktualisiert. Daraus entsteht eine konkrete Verbesserungsmaßnahme: Künftige Änderungen werden an einer zentralen Stelle dokumentiert und müssen von den betroffenen Verantwortlichen bestätigt werden. Diese Lösung kostet zunächst zusätzliche Zeit, soll aber verhindern, dass dieselbe Unklarheit erneut mehrere Tage Arbeit verursacht. Professionelle Kommunikation verbindet hier Fehleranalyse mit Prozessverbesserung, ohne persönliche Schuldzuweisungen zum Mittelpunkt zu machen.",
  "B2:technology": "Vor einer vollständigen Einführung empfiehlt sich daher ein begrenzter Pilot. In dieser Phase kann gemessen werden, bei welchen Aufgaben das System tatsächlich Zeit spart und wo zusätzliche Kontrollen notwendig sind. Ebenso sollte festgelegt werden, welche Fehler als kritisch gelten und wann ein Mensch die Entscheidung übernehmen muss. Ein Pilot ist jedoch nur dann aussagekräftig, wenn Erfolgskriterien vorher definiert werden. Sonst besteht die Gefahr, nachträglich nur die positiven Beobachtungen hervorzuheben. Neben technischer Leistung gehören deshalb Nutzerfreundlichkeit, Fehlerraten, Aufwand für Korrekturen und Auswirkungen auf bestehende Arbeitsabläufe in die Bewertung. Erst wenn diese Dimensionen gemeinsam betrachtet werden, lässt sich entscheiden, ob eine breitere Einführung sinnvoll ist.",
  "B2:society": "Auch der zeitliche Verlauf kann die Bewertung verändern. Eine neue Regelung kann kurzfristig Unzufriedenheit auslösen, weil Routinen verändert werden, und langfristig dennoch Vorteile bringen. Umgekehrt können anfängliche Verbesserungen später verschwinden, wenn sich Menschen an neue Anreize anpassen. Deshalb sollten soziale Entwicklungen nicht nur zu einem einzigen Zeitpunkt gemessen werden. Wichtig ist zudem, wer an Befragungen oder Datenerhebungen teilnimmt. Besonders belastete Gruppen haben möglicherweise weniger Zeit, ihre Erfahrungen ausführlich zu dokumentieren. Werden solche Unterschiede übersehen, entsteht ein unvollständiges Bild. Differenzierte Sozialanalyse verbindet daher quantitative Trends mit Informationen darüber, wie unterschiedliche Gruppen die Veränderung tatsächlich erleben.",
  "B2:climate-environment": "Hinzu kommt der sogenannte Rebound-Effekt: Wenn eine effizientere Technik die Nutzung günstiger macht, kann ein Teil der erwarteten Einsparung durch häufigere oder intensivere Nutzung verloren gehen. Das bedeutet nicht, dass Effizienzmaßnahmen nutzlos wären, zeigt aber, warum technische Berechnungen allein nicht immer die reale Wirkung vorhersagen. Auch soziale Aspekte spielen eine Rolle. Steigen Mieten nach einer Sanierung stark, können Haushalte verdrängt werden, obwohl das Gebäude weniger Energie verbraucht. Eine umfassende Bewertung fragt deshalb gleichzeitig nach Emissionen, Kosten, Verhalten und Verteilung. Politische Maßnahmen sind besonders robust, wenn sie technische Ziele mit sozialer Umsetzbarkeit verbinden und ihre Wirkung nach der Einführung weiter beobachten.",
  "B2:media-communication": "Im digitalen Umfeld kommt noch die Verbreitungslogik von Plattformen hinzu. Nutzer sehen nicht zwangsläufig die relevantesten Beiträge, sondern Inhalte, die durch persönliche Auswahl, Empfehlungen und Plattformmechanismen sichtbar werden. Dadurch kann der Eindruck entstehen, eine bestimmte Position sei sehr viel verbreiteter, als sie außerhalb des eigenen Informationsumfelds tatsächlich ist. Wer Medien kritisch nutzt, prüft deshalb nicht nur einzelne Aussagen, sondern auch, wie er überhaupt auf eine Quelle gestoßen ist. Gleichzeitig darf diese Vorsicht nicht in pauschales Misstrauen umschlagen. Verlässliche Orientierung entsteht durch nachvollziehbare Quellen, transparente Korrekturen und den Vergleich unabhängiger Berichte, nicht durch die Annahme, alle Darstellungen seien gleichermaßen unsicher.",
  "B2:education-policy": "Bei der Bewertung von Lernerfolg ist außerdem entscheidend, was überhaupt gemessen wird. Ein kurzer Test kann Faktenwissen zuverlässig erfassen, aber kaum zeigen, ob Lernende ein Problem auf eine neue Situation übertragen können. Projektarbeiten messen andere Fähigkeiten, sind jedoch schwieriger einheitlich zu bewerten. Wenn Institutionen nur einen Indikator verwenden, kann Unterricht sich stark auf genau diesen Indikator ausrichten. Eine ausgewogene Bewertung kombiniert deshalb mehrere Formen von Evidenz und berücksichtigt, dass unterschiedliche Lernziele unterschiedliche Aufgaben benötigen. Für politische Entscheidungen bedeutet das, dass Ranglisten oder einzelne Testergebnisse nicht ohne Kontext als vollständiges Bild der Bildungsqualität verstanden werden sollten.",
  "B2:economy-consumer": "Entscheidungen werden außerdem nicht ausschließlich rational im wirtschaftlichen Sinn getroffen. Menschen reagieren stärker auf mögliche Verluste als auf gleich große Gewinne, bevorzugen bekannte Marken oder überschätzen kurzfristige Rabatte. Unternehmen berücksichtigen solche Verhaltensmuster bei Preisgestaltung und Werbung. Für Verbraucher ist deshalb hilfreich, eine Entscheidung zeitlich zu verlangsamen: Welche Eigenschaften brauche ich wirklich, welche Kosten entstehen später und welche Information stammt aus unabhängigen Quellen? Auch Unternehmen profitieren von dieser Perspektive, wenn sie Investitionsentscheidungen nicht allein an einer optimistischen Prognose ausrichten. Szenarien mit unterschiedlichen Annahmen machen sichtbar, welche Entscheidung auch dann noch tragfähig bleibt, wenn sich Nachfrage, Kosten oder technische Bedingungen ungünstiger entwickeln.",
  "B2:culture-identity": "Sprache kann darüber hinaus gesellschaftliche Machtverhältnisse spiegeln. Wer eine dominante Sprache sicher beherrscht, erhält in Bildung und Beruf häufig leichter Zugang zu Informationen und Netzwerken. Gleichzeitig können Minderheitensprachen wichtige kulturelle und familiäre Funktionen behalten, selbst wenn sie im öffentlichen Raum weniger sichtbar sind. Mehrsprachige Gesellschaften stehen deshalb vor praktischen Fragen: In welchen Situationen braucht es Übersetzung, wie werden öffentliche Informationen zugänglich gemacht und welche Sprachen werden in Schulen gefördert? Solche Entscheidungen betreffen nicht nur Kommunikation, sondern auch Anerkennung und Teilhabe. Eine sachliche Diskussion vermeidet dabei die Annahme, der Gebrauch einer gemeinsamen Sprache und der Schutz sprachlicher Vielfalt müssten zwangsläufig Gegensätze sein.",
  "B2:presentations": "Bei der Vorbereitung hilft es außerdem, mögliche Einwände vorwegzunehmen. Wenn ein Ergebnis überraschend ist, sollte bereits eine Folie oder Notiz erklären, welche alternative Interpretation geprüft wurde. Dadurch wird die Fragerunde nicht zu einer Verteidigungssituation, sondern zu einer Fortsetzung der Analyse. Gleichzeitig darf eine Präsentation nicht mit allen denkbaren Details überladen werden. Hintergrundinformationen können bereitgehalten werden, während die Hauptdarstellung nur das enthält, was für die Entscheidung oder Diskussion wesentlich ist. Wer Daten präsentiert, übernimmt damit auch eine Auswahlverantwortung: Was wird hervorgehoben, was bleibt im Anhang und welche Unsicherheit muss direkt auf der Hauptfolie sichtbar sein?",
  "C1:academic-discourse": "Auf dieser Ebene gewinnt auch die Beziehung zwischen einzelnen Studien an Bedeutung. Zwei Untersuchungen können scheinbar widersprüchliche Ergebnisse liefern, obwohl sie unterschiedliche Populationen, Messinstrumente oder Zeiträume betrachten. Eine Literaturübersicht muss deshalb zunächst prüfen, ob die Befunde überhaupt direkt vergleichbar sind. Erst danach lässt sich sinnvoll über Übereinstimmung oder Widerspruch sprechen. Methodische Qualität ist ebenfalls nicht binär. Eine Studie kann bei der Datenerhebung sehr stark sein und dennoch nur eingeschränkte Aussagen über Kausalität erlauben. Fortgeschrittene Leser rekonstruieren daher die inferenzielle Kette: Welche Beobachtung wurde gemacht, welche Annahme verbindet sie mit der Schlussfolgerung und welche alternativen Erklärungen bleiben möglich? In der eigenen Darstellung sollte diese Struktur sichtbar werden, damit aus einer differenzierten Quellenlage keine künstlich eindeutige Geschichte entsteht.",
  "C1:formal-writing": "Je sensibler der institutionelle Kontext, desto wichtiger wird außerdem die Dokumentationsfunktion eines Textes. Eine E-Mail oder ein Memo kann später als Nachweis dafür dienen, welche Information zu welchem Zeitpunkt vorlag und welche Entscheidung daraufhin getroffen wurde. Vage Formulierungen, die im Gespräch freundlich wirken, können in diesem Zusammenhang problematisch sein. Gleichzeitig ist übermäßige Absicherung ebenso unpraktisch, weil sie Verantwortlichkeiten verwischt und Texte unnötig verlängert. Professionelles Schreiben verlangt daher eine bewusste Gewichtung: Welche Aussage ist Tatsache, welche Einschätzung, welche Bitte und welche verbindliche Entscheidung? Auch Verweise auf Anlagen oder frühere Absprachen sollten so formuliert sein, dass Leser den relevanten Zusammenhang ohne zusätzliche Suche verstehen. Präzision ist damit nicht nur eine stilistische Qualität, sondern Teil organisatorischer Verlässlichkeit.",
  "C1:nuanced-argument": "Ein weiterer Prüfstein ist die Behandlung von Basisraten und Vergleichsmaßstäben. Ein spektakulärer Einzelfall kann intuitiv sehr überzeugend wirken, obwohl er für die Häufigkeit eines Phänomens kaum aussagekräftig ist. Umgekehrt kann ein statistisch stabiler Zusammenhang praktisch wenig bedeutsam sein. Wer argumentiert, muss daher entscheiden, welche Art von Evidenz zur jeweiligen Behauptung passt. Ebenso wichtig ist die Möglichkeit der Widerlegung: Eine Position, die jedes denkbare Ergebnis nachträglich als Bestätigung interpretiert, lässt sich kaum kritisch prüfen. Gute Argumentation nennt deshalb zumindest implizit, welche Beobachtung die eigene Einschätzung schwächen würde. Das zwingt zu präziseren Aussagen und verhindert, dass Unsicherheit nur rhetorisch erwähnt wird, ohne echte Konsequenzen für die Schlussfolgerung zu haben.",
  "C1:data-reports": "Zusätzlich kann die Zusammensetzung einer Population Trends erzeugen, die auf individueller Ebene gar nicht existieren. Wenn beispielsweise der Anteil einer besonders leistungsstarken Gruppe wächst, kann der Gesamtdurchschnitt steigen, obwohl sich innerhalb jeder Gruppe nichts verändert hat. Umgekehrt kann eine Verbesserung in mehreren Teilgruppen im Gesamtergebnis verdeckt werden. Solche Effekte machen Segmentierung notwendig, dürfen aber nicht zu beliebig vielen Unteranalysen führen, bis zufällig ein gewünschtes Muster erscheint. Ein seriöser Bericht erklärt daher, welche Aufteilungen fachlich begründet waren und welche Analysen explorativ sind. Auch fehlende Daten verdienen Aufmerksamkeit. Wenn Ausfälle systematisch bestimmte Fälle betreffen, kann die verbleibende Stichprobe ein verzerrtes Bild liefern. Transparenz über diese Grenzen ermöglicht bessere Entscheidungen als scheinbare Präzision.",
  "C1:negotiation": "Zur Vorbereitung gehört schließlich die Kenntnis der eigenen Alternative, falls keine Einigung zustande kommt. Wer keine realistische Ausweichoption kennt, bewertet Zugeständnisse leicht falsch. Ebenso sollte eingeschätzt werden, welche Alternativen die andere Seite vermutlich besitzt, ohne deren Motive zu unterstellen. In komplexen Verhandlungen können mehrere Themen gekoppelt werden: Eine Partei akzeptiert einen späteren Termin, wenn dafür der Umfang erweitert wird; die andere stimmt zusätzlicher Qualitätssicherung zu, wenn Prioritäten reduziert werden. Solche Pakete schaffen Spielraum, weil Interessen unterschiedlich gewichtet werden. Voraussetzung ist jedoch, dass jede Vereinbarung operationalisierbar bleibt. Unklare Begriffe wie „zeitnah“, „ausreichend“ oder „bestmöglich“ sollten dort präzisiert werden, wo später unterschiedliche Interpretationen erhebliche Folgen hätten.",
  "C1:media-analysis": "Auf sprachlicher Ebene sind auch Präsuppositionen und implizite Bewertungen relevant. Eine Frage wie „Warum ist die Reform gescheitert?“ setzt bereits voraus, dass ein Scheitern feststeht, während „Welche Ergebnisse hatte die Reform?“ den Ausgang offener lässt. Ähnliche Effekte entstehen durch Verben wie „zugeben“, „behaupten“ oder „feststellen“, die unterschiedliche Haltungen gegenüber einer Quelle signalisieren. Fortgeschrittene Analyse untersucht solche Signale, ohne jede stilistische Entscheidung automatisch als bewusste Manipulation zu interpretieren. Entscheidend ist das Muster im gesamten Beitrag: Werden bestimmte Akteure regelmäßig mit skeptischer Distanz zitiert, andere dagegen als neutrale Autorität dargestellt? Werden Unsicherheiten symmetrisch behandelt? Erst die Verbindung von Quellenprüfung, Textstruktur und sprachlicher Detailanalyse erlaubt eine belastbare Einschätzung der Rahmung.",
  "C1:science-ethics": "Besonders schwierig wird die Entscheidung bei großer Unsicherheit über seltene, aber potenziell schwere Schäden. Ein strenges Vorsorgeprinzip kann verlangen, eine Anwendung zunächst zu begrenzen; ein zu weit gefasstes Verständnis von Vorsorge könnte jedoch auch nützliche Innovationen blockieren. Deshalb muss erklärt werden, wie Wahrscheinlichkeit, Schadenshöhe und Reversibilität gegeneinander gewichtet werden. Reversible Pilotprojekte erlauben andere Entscheidungen als Systeme, deren Folgen kaum rückgängig zu machen sind. Ebenso verändert die Verteilung der Risiken die ethische Bewertung: Ein durchschnittlicher gesellschaftlicher Nutzen rechtfertigt nicht automatisch, dass eine kleine Gruppe unverhältnismäßig hohe Risiken trägt. Solche Fragen lassen sich selten durch eine einzige Formel lösen, aber sie können systematisch sichtbar gemacht und öffentlich begründet werden.",
  "C1:institutions-society": "Dieses Problem wird häufig als Zielverschiebung sichtbar: Sobald ein Messwert mit starken Konsequenzen verbunden ist, verändert sich das Verhalten gegenüber dem Messwert selbst. Organisationen investieren dann möglicherweise mehr Energie in die Optimierung der Kennzahl als in das ursprüngliche Ziel, das sie nur unvollständig abbildet. Eine institutionelle Antwort besteht nicht darin, Messung abzuschaffen, sondern verschiedene Informationsquellen zu kombinieren und Anreize regelmäßig auf unerwünschte Nebenwirkungen zu prüfen. Außerdem sollte klar sein, wer Regeln anpassen darf und auf welcher Evidenzbasis dies geschieht. Institutionen benötigen Stabilität, damit Beteiligte planen können, zugleich aber Lernfähigkeit, wenn die tatsächlichen Wirkungen von ursprünglichen Annahmen abweichen. Dieses Spannungsverhältnis prägt viele Reformprozesse.",
  "C1:presentations-debate": "Auch die kognitive Belastung des Publikums muss berücksichtigt werden. Eine Folie mit zahlreichen Zahlen, Fachbegriffen und langen Sätzen zwingt Zuhörer, gleichzeitig zu lesen, zu rechnen und dem gesprochenen Argument zu folgen. Selbst korrekte Information kann dadurch ihre Wirkung verlieren. Fortgeschrittene Präsentationen verteilen Komplexität daher über Zeit: zunächst Orientierung, dann Evidenz, anschließend Interpretation. Wiederholungen können gezielt eingesetzt werden, wenn sie die argumentative Struktur verdeutlichen, sollten aber nicht bloß denselben Satz neu verpacken. In der Debatte hilft diese Struktur ebenfalls, weil Antworten auf Rückfragen an einen bereits etablierten Punkt anknüpfen können. So bleibt auch eine spontane Diskussion für das Publikum nachvollziehbar.",
  "C1:synthesis-mastery": "Bei mehreren Quellen sollte zudem ihre unterschiedliche epistemische Rolle berücksichtigt werden. Eine empirische Studie, ein Kommentar, ein offizielles Dokument und ein persönlicher Erfahrungsbericht liefern nicht dieselbe Art von Evidenz, können aber jeweils relevante Informationen beitragen. Eine Synthese macht diese Unterschiede sichtbar, statt alle Aussagen in eine gemeinsame Liste zu überführen. Besonders anspruchsvoll ist der Umgang mit teilweise übereinstimmenden Quellen: Zwei Autoren können dieselbe Diagnose teilen, aber aus unterschiedlichen Gründen zu gegensätzlichen Empfehlungen kommen. Dann sollte die Darstellung nicht nur den Konflikt nennen, sondern die zugrunde liegenden Bewertungsmaßstäbe rekonstruieren. Die eigene Schlussfolgerung gewinnt an Qualität, wenn sie erklärt, welche Kriterien den Ausschlag geben und welche Unsicherheit auch nach dieser Abwägung bestehen bleibt."
};
